import unittest

from retry import should_retry


class ShouldRetryTest(unittest.TestCase):
    def test_retryable_statuses(self):
        for status in (408, 429, 500, 502, 503, 504):
            with self.subTest(status=status):
                self.assertIs(should_retry(status), True)

    def test_non_retryable_statuses(self):
        for status in (100, 200, 400, 401, 404, 425, 501, 505, 599, 600, None, "503"):
            with self.subTest(status=status):
                self.assertIs(should_retry(status), False)


if __name__ == "__main__":
    unittest.main()
